+@page "/track"
+@attribute [Authorize]
+@rendermode InteractiveWebAssembly
+
+@inject IShipmentService ShipmentService
+
+<PageTitle>Track Shipment</PageTitle>
+
+<h1>Track a Shipment</h1>
+
+<div class="row mb-4">
+    <div class="col-md-6">
+        <div class="input-group">
+            <input class="form-control" placeholder="Enter tracking number..." @bind="trackingNumber" @onkeydown="HandleKeyDown" />
+            <button class="btn btn-primary" @onclick="Search">Search</button>
+        </div>
+    </div>
+</div>
+
+@if (isLoading)
+{
+    <p><em>Searching...</em></p>
+}
+else if (searched && shipment is null)
+{
+    <div class="alert alert-warning">No shipment found with tracking number "<strong>@searchedNumber</strong>".</div>
+}
+else if (shipment is not null)
+{
+    <div class="card">
+        <div class="card-header">
+            <h4>Shipment: @shipment.TrackingNumber</h4>
+        </div>
+        <div class="card-body">
+            <div class="row">
+                <div class="col-md-6">
+                    <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></p>
+                    <p><strong>Origin:</strong> @shipment.Origin</p>
+                    <p><strong>Destination:</strong> @shipment.Destination</p>
+                    <p><strong>Description:</strong> @shipment.Description</p>
+                </div>
+                <div class="col-md-6">
+                    <p><strong>Created:</strong> @shipment.CreatedDate.ToString("yyyy-MM-dd")</p>
+                    <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "N/A")</p>
+                    <p><strong>Actual Delivery:</strong> @(shipment.ActualDelivery?.ToString("yyyy-MM-dd") ?? "Not yet delivered")</p>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private string trackingNumber = "";
+    private string searchedNumber = "";
+    private Shipment? shipment;
+    private bool isLoading;
+    private bool searched;
+
+    private async Task Search()
+    {
+        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
+
+        isLoading = true;
+        searched = false;
+        shipment = null;
+
+        try
+        {
+            searchedNumber = trackingNumber.Trim();
+            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
+        }
+        catch
+        {
+            shipment = null;
+        }
+        finally
+        {
+            isLoading = false;
+            searched = true;
+        }
+    }
+
+    private async Task HandleKeyDown(KeyboardEventArgs e)
+    {
+        if (e.Key == "Enter") await Search();
+    }
+
+    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
+    {
+        ShipmentStatus.Pending => "bg-secondary",
+        ShipmentStatus.PickedUp => "bg-info",
+        ShipmentStatus.InTransit => "bg-primary",
+        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
+        ShipmentStatus.Delivered => "bg-success",
+        ShipmentStatus.Delayed => "bg-danger",
+        _ => "bg-secondary"
+    };
+}
